package app.exteraless.settings;
import android.animation.ObjectAnimator;import android.app.Activity;import android.view.View;import android.widget.TextView;import android.widget.Toast;
import org.telegram.messenger.AndroidUtilities;import org.telegram.ui.ActionBar.AlertDialog;import org.telegram.ui.ActionBar.Theme;import org.telegram.ui.Components.UItem;import org.telegram.ui.Components.UniversalAdapter;import org.telegram.ui.Components.UniversalFragment;import app.exteraless.fun.ChatDanceMode;import java.util.ArrayList;
public class RoflanDanceStudioActivity extends UniversalFragment{
 private static final int ENABLE=1,MODE=2,INTENSITY=3,PREVIEW=4;
 @Override protected CharSequence getTitle(){return "Танцующие чаты";}
 @Override protected void fillItems(ArrayList<UItem>a,UniversalAdapter adapter){a.add(UItem.asHeader("Анимация списка диалогов"));a.add(UItem.asButton(ENABLE,"Танцы · "+(ChatDanceMode.isEnabled()?"Включены":"Выключены")));a.add(UItem.asButton(MODE,"Хореография · "+ChatDanceMode.MODE_NAMES[ChatDanceMode.mode()]));a.add(UItem.asButton(INTENSITY,"Амплитуда · "+new String[]{"Мягкая","Средняя","Выраженная"}[ChatDanceMode.intensity()-1]));a.add(UItem.asButton(PREVIEW,"Посмотреть анимацию"));a.add(UItem.asShadow(null));a.add(UItem.asHeader("Оптимизация"));a.add(UItem.asButton(90,"Анимируются только видимые ячейки; трансформации сбрасываются при выключении."));}
 @Override protected void onClick(UItem item,View view,int position,float x,float y){Activity a=getParentActivity();if(a==null)return;if(item.id==ENABLE){ChatDanceMode.setEnabled(!ChatDanceMode.isEnabled());refresh();Toast.makeText(a,ChatDanceMode.isEnabled()?"Танцы включены":"Танцы выключены",Toast.LENGTH_SHORT).show();}else if(item.id==MODE)new AlertDialog.Builder(a).setTitle("Выбери хореографию").setItems(ChatDanceMode.MODE_NAMES,(d,w)->{ChatDanceMode.setMode(w);refresh();}).setNegativeButton("Отмена",null).show();else if(item.id==INTENSITY)new AlertDialog.Builder(a).setTitle("Амплитуда").setItems(new String[]{"Мягкая","Средняя","Выраженная"},(d,w)->{ChatDanceMode.setIntensity(w+1);refresh();}).setNegativeButton("Отмена",null).show();else if(item.id==PREVIEW)preview(a);}
 @Override protected boolean onLongClick(UItem item,View view,int position,float x,float y){return false;}
 private void preview(Activity a){TextView v=new TextView(a);v.setText("Алексей\nПривет! Как дела?");v.setTextSize(16);v.setPadding(AndroidUtilities.dp(22),AndroidUtilities.dp(16),AndroidUtilities.dp(22),AndroidUtilities.dp(16));v.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlackText));v.setBackground(Theme.createRoundRectDrawable(AndroidUtilities.dp(14),Theme.getColor(Theme.key_windowBackgroundWhite)));AlertDialog d=new AlertDialog.Builder(a).setTitle("Предпросмотр").setView(v).setPositiveButton("Готово",null).create();d.setOnShowListener(x->{ObjectAnimator an;switch(ChatDanceMode.mode()){case ChatDanceMode.SWING:an=ObjectAnimator.ofFloat(v,View.ROTATION,0,-3,0,3,0);break;case ChatDanceMode.PULSE:an=ObjectAnimator.ofFloat(v,View.SCALE_X,1,1.06f,1);break;case ChatDanceMode.CHAOS:an=ObjectAnimator.ofFloat(v,View.TRANSLATION_X,0,12,-12,0);break;default:an=ObjectAnimator.ofFloat(v,View.TRANSLATION_Y,0,-12,0,5,0);break;}an.setDuration(720);an.setRepeatCount(2);an.start();});d.show();}
 private void refresh(){if(listView!=null)listView.adapter.update(true);}
}